const (
	EnvRegion     = "TERRABASE_REGION"
	WANFreshFor   = 2 * time.Minute
	MaxWANRegions = 64
	// WANMaxValue preserves exact integer counts in shared float64 history.
	WANMaxValue  = 1<<53 - 1
	wanBodyBytes = 1 << 20
)

// WANObservation measures incoming replication at one local receiver.
// ObservedAt is the original loopback scrape time, never delivery time.
type WANObservation struct {
	ObservedAt     time.Time   `json:"observed_at"`
	ReceiverRegion string      `json:"receiver_region"`
	Sources        []WANSource `json:"sources"`
}

type WANSource struct {
	SourceRegion       string   `json:"source_region"`
	LagGroups          *float64 `json:"lag_groups"`
	StalenessSeconds   *float64 `json:"staleness_seconds"`
	Members            *float64 `json:"members"`
	Unregistered       *float64 `json:"unregistered"`
	Conflicts          *float64 `json:"conflicts"`
	AheadFailuresTotal *float64 `json:"ahead_failures_total,omitempty"`
}

func (w WANObservation) Fresh(now time.Time) bool {
	return !w.ObservedAt.IsZero() && !w.ObservedAt.After(now) && now.Sub(w.ObservedAt) <= WANFreshFor
}

func (w WANObservation) Validate() error {
	_, offset := w.ObservedAt.Zone()
	if w.ObservedAt.UnixMilli() <= 0 || offset != 0 || !wanRegionRE.MatchString(w.ReceiverRegion) || len(w.Sources) == 0 || len(w.Sources) > MaxWANRegions {
		return errors.New("invalid WAN observation time or source count")
	}
	seen := make(map[string]bool, len(w.Sources))
	for _, source := range w.Sources {
		if !wanRegionRE.MatchString(source.SourceRegion) || seen[source.SourceRegion] {
			return errors.New("invalid or duplicate WAN source region")
		}
		seen[source.SourceRegion] = true
		for _, value := range []*float64{source.LagGroups, source.StalenessSeconds, source.Members, source.Unregistered, source.Conflicts} {
			if value == nil || !validWANValue(*value) {
				return errors.New("missing or invalid WAN gauge")
			}
		}
		for _, value := range []*float64{source.LagGroups, source.Members, source.Unregistered, source.Conflicts, source.AheadFailuresTotal} {
			if value != nil && (!validWANValue(*value) || math.Trunc(*value) != *value) {
				return errors.New("WAN count must be an exact nonnegative integer")
			}
		}
	}
	return nil
}

func validWANValue(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0) && value >= 0 && value <= WANMaxValue
}

func ParseWANMetrics(data []byte, receiverRegion string, observedAt time.Time) (*WANObservation, error) {
	if len(data) > wanBodyBytes {
		return nil, errors.New("WAN metrics exceed size bound")
	}
	sources := make(map[string]*WANSource)
	seen := make(map[string]bool)
	scanner := bufio.NewScanner(bytes.NewReader(data))
	scanner.Buffer(make([]byte, 4096), 16<<10)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		end := strings.IndexAny(line, "{ \t")
		if end < 0 {
			end = len(line)
		}
		metric := line[:end]
		switch metric {
		case "terrabase_wan_lag", "terrabase_wan_staleness_seconds", "terrabase_wan_members",
			"terrabase_wan_unregistered", "terrabase_wan_conflicts", "terrabase_wan_failures_total":
		default:
			continue
		}
		labels, raw, err := parseWANLabels(strings.TrimSpace(line[end:]))
		if err != nil {
			return nil, err
		}
		region, reason := labels["region"], labels["reason"]
		_, hasReason := labels["reason"]
		if !wanRegionRE.MatchString(region) || (metric == "terrabase_wan_failures_total" && !slices.Contains([]string{"heads", "pull", "apply", "ahead"}, reason)) ||
			(metric != "terrabase_wan_failures_total" && hasReason) {
			return nil, errors.New("invalid WAN region or reason label")
		}
		value, err := strconv.ParseFloat(raw, 64)
		if err != nil || !validWANValue(value) || (metric != "terrabase_wan_staleness_seconds" && math.Trunc(value) != value) {
			return nil, errors.New("invalid WAN metric value")
		}
		key := metric + "\x00" + region + "\x00" + reason
		if seen[key] || len(seen) >= MaxWANRegions*9 {
			return nil, errors.New("duplicate or excessive WAN metrics")
		}
		seen[key] = true
		if metric == "terrabase_wan_failures_total" && reason != "ahead" {
			continue
		}
		source := sources[region]
		if source == nil {
			if len(sources) == MaxWANRegions {
				return nil, errors.New("WAN metrics exceed source count bound")
			}
			source = &WANSource{SourceRegion: region}
			sources[region] = source
		}
		switch metric {
		case "terrabase_wan_lag":
			source.LagGroups = new(value)
		case "terrabase_wan_staleness_seconds":
			source.StalenessSeconds = new(value)
		case "terrabase_wan_members":
			source.Members = new(value)
		case "terrabase_wan_unregistered":
			source.Unregistered = new(value)
		case "terrabase_wan_conflicts":
			source.Conflicts = new(value)
		case "terrabase_wan_failures_total":
			source.AheadFailuresTotal = new(value)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(sources) == 0 {
		return nil, nil
	}
	observation := &WANObservation{ObservedAt: observedAt, ReceiverRegion: receiverRegion}
	for _, source := range sources {
		observation.Sources = append(observation.Sources, *source)
	}
	slices.SortFunc(observation.Sources, func(a, b WANSource) int { return strings.Compare(a.SourceRegion, b.SourceRegion) })
	if err := observation.Validate(); err != nil {
		return nil, err
	}
	return observation, nil
}

func parseWANLabels(raw string) (map[string]string, string, error) {
	labels := make(map[string]string)
	if !strings.HasPrefix(raw, "{") {
		return nil, "", errors.New("WAN metrics require region labels")
	}
	raw = strings.TrimSpace(raw[1:])
	for {
		match := wanLabelRE.FindStringSubmatch(raw)
		if match == nil {
			return nil, "", errors.New("malformed WAN metric labels")
		}
		name := match[1]
		value, err := strconv.Unquote(match[2])
		if _, duplicate := labels[name]; err != nil || duplicate {
			return nil, "", errors.New("invalid or duplicate WAN label")
		}
		switch name {
		case "region", "reason":
		case "otel_scope_name":
			if value != "TerraScale.TerraBase" {
				return nil, "", errors.New("unexpected WAN instrument scope")
			}
		case "otel_scope_version":
			if len(value) > 64 {
				return nil, "", errors.New("WAN instrument version exceeds bound")
			}
		default:
			return nil, "", errors.New("unsupported WAN metric label")
		}
		labels[name] = value
		raw = strings.TrimSpace(raw[len(match[0]):])
		if tail, ok := strings.CutPrefix(raw, "}"); ok {
			fields := strings.Fields(tail)
			if len(fields) != 1 {
				return nil, "", errors.New("WAN metric requires one value without an external timestamp")
			}
			return labels, fields[0], nil
		}
		tail, ok := strings.CutPrefix(raw, ",")
		if !ok {
			return nil, "", errors.New("malformed WAN label separator")
		}
		raw = strings.TrimSpace(tail)
	}
}

var start = time.Date(2026, 10, 10, 12, 0, 0, 0, time.UTC)

type clock struct{ now time.Time }

func (c *clock) Now() time.Time { return c.now }

func startNATS(t *testing.T) *nats.Conn {
	t.Helper()
	// The default payload limit is 1 MiB; raise it so oversize rollups reach the follower's own limit.
	server, err := natsserver.NewServer(&natsserver.Options{Host: "127.0.0.1", Port: -1, NoLog: true, NoSigs: true, MaxPayload: 4 << 20})
	if err != nil {
		t.Fatal(err)
	}
	server.Start()
	t.Cleanup(func() { server.Shutdown(); server.WaitForShutdown() })
	if !server.ReadyForConnections(5 * time.Second) {
		t.Fatal("nats not ready")
	}
	conn, err := nats.Connect(server.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	return conn
}

func publish(t *testing.T, conn *nats.Conn, cell string, r rollup) {
	t.Helper()
	data, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	publishRaw(t, conn, cell, data)
}

func publishRaw(t *testing.T, conn *nats.Conn, cell string, data []byte) {
	t.Helper()
	if err := conn.Publish(protocol.TerraBaseObservabilitySubject(cell), data); err != nil {
		t.Fatal(err)
	}
}

func member(name string, at time.Time, top ...entry) rollup {
	return rollup{Version: version, Cell: "gru", Member: name, At: at, WindowMs: 5000, Top: top}
}

func awaitDatabases(t *testing.T, f *Follower, done func([]globalview.Database) bool) []globalview.Database {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		list := f.Databases()
		if done(list) {
			return list
		}
		if time.Now().After(deadline) {
			t.Fatalf("databases never converged, last: %+v", list)
		}
		time.Sleep(10 * time.Millisecond)
	}
}

func hasID(list []globalview.Database, id string) bool {
	for _, d := range list {
		if d.ID == id {
			return true
		}
	}
	return false
}

const (
	// version is the rollup wire version this reader accepts.
	version = 1
	// maxMessage bounds one rollup. Larger messages are dropped undecoded.
	maxMessage = 1 << 20
	// maxMembers bounds the members kept. A full table prunes stale members first.
	maxMembers = 64
	// maxTop is the most databases a member lists, the producer's cap. It bounds memory.
	maxTop = 60
	// maxPeers is the most peer regions a member lists per database. It bounds memory.
	maxPeers = 64
	// maxDatabases matches globalview's cap on the dashboard list.
	maxDatabases = 10
	// staleAfter drops a member whose rollup is older: six missed publishes.
	staleAfter = 30 * time.Second
)

// rollup is the part of a member's TerraBase rollup the dashboard reads.
type rollup struct {
	Version  int       `json:"v"`
	Cell     string    `json:"cell"`
	Member   string    `json:"member"`
	At       time.Time `json:"at"`
	WindowMs int64     `json:"windowMs"`
	Top      []entry   `json:"top"`
}

// entry is one database in a member's rollup over its window.
type entry struct {
	Org           string  `json:"org"`
	Project       string  `json:"project"`
	Database      string  `json:"database"`
	SentBytes     uint64  `json:"sentBytes"`
	ReceivedBytes uint64  `json:"receivedBytes"`
	Reads         uint64  `json:"reads"`
	Writes        uint64  `json:"writes"`
	StorageBytes  uint64  `json:"storageBytes"` // zero when the member does not know it
	LagSeconds    float64 `json:"lagSeconds"`
	Peers         []peer  `json:"peers"`
}

// peer is one peer region's share of a database over the member's window.
type peer struct {
	Region        string `json:"region"`
	SentBytes     uint64 `json:"sentBytes"`
	ReceivedBytes uint64 `json:"receivedBytes"`
}

// peerKey names one peer region's share of one database.
type peerKey struct{ database, region string }

// Follower holds the newest rollup of each TerraBase member of one cell.
type Follower struct {
	now     func() time.Time
	mu      sync.Mutex
	members map[string]rollup
}

func follow(ctx context.Context, conn *nats.Conn, cell string, now func() time.Time) *Follower {
	follower := &Follower{now: now, members: map[string]rollup{}}
	sub, err := conn.Subscribe(protocol.TerraBaseObservabilitySubject(cell), func(msg *nats.Msg) {
		follower.accept(cell, msg.Data)
	})
	if err != nil {
		slog.Warn("terrabase database stats not followed", observability.ComponentKey, "terrabasestats", "error", err)
		return follower
	}
	context.AfterFunc(ctx, func() {
		if err := sub.Unsubscribe(); err != nil {
			slog.Debug("terrabase database stats subscription not closed", observability.ComponentKey, "terrabasestats", "error", err)
		}
	})
	return follower
}

func (f *Follower) accept(cell string, data []byte) {
	var r rollup
	if err := protocol.DecodeTolerant(data, &r, maxMessage); err != nil {
		slog.Debug("terrabase rollup dropped", observability.ComponentKey, "terrabasestats", "error", err)
		return
	}
	if r.Version != version || r.Cell != cell || r.Member == "" || r.WindowMs <= 0 {
		return
	}
	r.Top = r.Top[:min(len(r.Top), maxTop)]
	for i := range r.Top {
		r.Top[i].Peers = r.Top[i].Peers[:min(len(r.Top[i].Peers), maxPeers)]
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if old, ok := f.members[r.Member]; ok {
		if r.At.Before(old.At) {
			return
		}
	} else {
		if len(f.members) >= maxMembers {
			f.prune(f.now())
		}
		if len(f.members) >= maxMembers {
			return
		}
	}
	f.members[r.Member] = r
}

func (f *Follower) prune(now time.Time) {
	for name, r := range f.members {
		if r.At.Before(now.Add(-staleAfter)) {
			delete(f.members, name)
		}
	}
}

func (f *Follower) Databases() []globalview.Database {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.prune(f.now())
	merged := map[string]*globalview.Database{}
	peers := map[peerKey]*globalview.DatabasePeer{}
	for _, r := range f.members {
		seconds := float64(r.WindowMs) / 1000
		for _, e := range r.Top {
			if e.Database == "" {
				continue
			}
			d, ok := merged[e.Database]
			if !ok {
				d = &globalview.Database{ID: e.Database, Org: e.Org, Project: e.Project}
				merged[e.Database] = d
			}
			d.ReplicationBytesPerSecond += float64(e.SentBytes+e.ReceivedBytes) / seconds
			d.SentBytesPerSecond += float64(e.SentBytes) / seconds
			d.ReceivedBytesPerSecond += float64(e.ReceivedBytes) / seconds
			d.ReadsPerSecond += float64(e.Reads) / seconds
			d.WritesPerSecond += float64(e.Writes) / seconds
			d.StorageBytes = max(d.StorageBytes, int64(e.StorageBytes))
			d.LagSeconds = max(d.LagSeconds, e.LagSeconds)
			for _, p := range e.Peers {
				key := peerKey{database: e.Database, region: p.Region}
				sum, ok := peers[key]
				if !ok {
					sum = &globalview.DatabasePeer{Region: p.Region}
					peers[key] = sum
				}
				sum.SentBytesPerSecond += float64(p.SentBytes) / seconds
				sum.ReceivedBytesPerSecond += float64(p.ReceivedBytes) / seconds
			}
		}
	}
	for key, sum := range peers {
		merged[key.database].Peers = append(merged[key.database].Peers, *sum)
	}
	out := make([]globalview.Database, 0, len(merged))
	for _, d := range merged {
		out = append(out, *d)
	}
	slices.SortFunc(out, func(a, b globalview.Database) int {
		return cmp.Or(cmp.Compare(b.ReplicationBytesPerSecond, a.ReplicationBytesPerSecond), strings.Compare(a.ID, b.ID))
	})
	return out[:min(len(out), maxDatabases)]
}

func Regional(cell string, tokens ...string) string {
	root, err := RegionalRoot(cell)
	if err != nil {
		return ""
	}
	return joinSubject(root, tokens)
}

func joinSubject(root string, tokens []string) string {
	if len(tokens) == 0 {
		return root
	}
	var builder strings.Builder
	builder.WriteString(root)
	for index, token := range tokens {
		for part := range strings.SplitSeq(token, ".") {
			if !validFamilyToken(part, index == len(tokens)-1) {
				return ""
			}
		}
		builder.WriteByte('.')
		builder.WriteString(token)
	}
	result := builder.String()
	// ">" may only terminate the whole subject.
	if index := strings.Index(result, ">"); index >= 0 && index != len(result)-1 {
		return ""
	}
	return result
}

func validFamilyToken(token string, last bool) bool {
	switch token {
	case "*", TemplateSubject:
		return true
	case ">":
		return last
	}
	if token == "" || len(token) > 128 {
		return false
	}
	for _, character := range token {
		switch {
		case character >= 'a' && character <= 'z', character >= 'A' && character <= 'Z',
			character >= '0' && character <= '9', character == '-', character == '_':
		default:
			return false
		}
	}
	return true
}

func CanonicalRegion(region string) (string, error) {
	if region == "" || len(region) > 63 {
		return "", fmt.Errorf("%w: region length is out of bounds", ErrInvalidSubjectToken)
	}
	region = strings.ToUpper(region)
	if region == "GLOBAL" {
		return region, nil
	}
	previousHyphen := true
	for _, character := range region {
		if character == '-' {
			if previousHyphen {
				return "", ErrInvalidSubjectToken
			}
			previousHyphen = true
			continue
		}
		if character < 'A' || character > 'Z' {
			if character < '0' || character > '9' {
				return "", ErrInvalidSubjectToken
			}
		}
		previousHyphen = false
	}
	if previousHyphen {
		return "", ErrInvalidSubjectToken
	}
	return region, nil
}

func RegionToken(region string) (string, error) {
	canonical, err := CanonicalRegion(region)
	if err != nil {
		return "", err
	}
	return strings.ToLower(canonical), nil
}

func RegionalRoot(region string) (string, error) {
	token, err := RegionToken(region)
	if err != nil || token == GlobalScope {
		return "", ErrInvalidSubjectToken
	}
	return SubjectRoot + "." + token, nil
}

func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

func NewServer(opts *Options) (*Server, error) {
	setBaselineOptions(opts)

	// Process TLS options, including whether we require client certificates.
	tlsReq := opts.TLSConfig != nil
	verify := (tlsReq && opts.TLSConfig.ClientAuth == tls.RequireAndVerifyClientCert)

	// Create our server's nkey identity.
	kp, _ := nkeys.CreateServer()
	pub, _ := kp.PublicKey()

	// Create an xkey for encrypting messages from this server.
	var xkp nkeys.KeyPair
	var xpub string
	if !fips140.Enabled() {
		xkp, _ = nkeys.CreateCurveKeys()
		xpub, _ = xkp.PublicKey()
	}

	serverName := pub
	if opts.ServerName != _EMPTY_ {
		serverName = opts.ServerName
	}

	httpBasePath := normalizeBasePath(opts.HTTPBasePath)

	// Validate some options. This is here because we cannot assume that
	// server will always be started with configuration parsing (that could
	// report issues). Its options can be (incorrectly) set by hand when
	// server is embedded. If there is an error, return nil.
	if err := validateOptions(opts); err != nil {
		return nil, err
	}

func (s *Server) ClientURL() string {
	// FIXME(dlc) - should we add in user and pass if defined single?
	opts := s.getOpts()
	var u url.URL
	u.Scheme = "nats"
	if opts.TLSConfig != nil {
		u.Scheme = "tls"
	}
	u.Host = net.JoinHostPort(opts.Host, fmt.Sprintf("%d", opts.Port))
	return u.String()
}

	// We've finished starting up.
	close(s.startupComplete)

	// Wait for clients.
	if !opts.DontListen {
		s.AcceptLoop(clientListenReady)
	} else {
		// TerraScale patch for v2.15.0: routes still need the readiness signal
		// when the client listener is deliberately disabled.
		close(clientListenReady)
	}

	// Bring OSCP Response cache online after accept loop started in anticipation of NATS-enabled cache types
	s.startOCSPResponseCache()
}

func (s *Server) AcceptLoop(clr chan struct{}) {
	// If we were to exit before the listener is setup properly,
	// make sure we close the channel.
	defer func() {
		if clr != nil {
			close(clr)
		}
	}()

	if s.isShuttingDown() {
		return
	}

	// Snapshot server options.
	opts := s.getOpts()

	// Setup state that can enable shutdown
	s.mu.Lock()
	hp := net.JoinHostPort(opts.Host, strconv.Itoa(opts.Port))
	l, e := s.getServerListener(hp)
	s.listenerErr = e
	if e != nil {
		s.mu.Unlock()
		s.Fatalf("Error listening on port: %s, %q", hp, e)
		return
	}
	s.Noticef("Listening for client connections on %s",
		net.JoinHostPort(opts.Host, strconv.Itoa(l.Addr().(*net.TCPAddr).Port)))

	// Alert if PROXY protocol is enabled
	if opts.ProxyProtocol {
		s.Noticef("PROXY protocol enabled for client connections")
	}

	// Alert of TLS enabled.
	if opts.TLSConfig != nil {
		// "TLS Handshake First" without a fallback delay always requires the
		// handshake, which overrides "allow_non_tls".
		tlsHandshakeFirstOnly := opts.TLSHandshakeFirst && opts.TLSHandshakeFirstFallback == 0
		if opts.AllowNonTLS && !tlsHandshakeFirstOnly {
			s.Noticef("TLS available for client connections")
		} else {
			s.Noticef("TLS required for client connections")
		}
		if tlsHandshakeFirstOnly {
			s.Warnf("Clients that are not using \"TLS Handshake First\" option will fail to connect")
		}
	}

	// If server was started with RANDOM_PORT (-1), opts.Port would be equal
	// to 0 at the beginning this function. So we need to get the actual port
	if opts.Port == 0 {
		// Write resolved port back to options.
		opts.Port = l.Addr().(*net.TCPAddr).Port
	}

	// Now that port has been set (if it was set to RANDOM), set the
	// server's info Host/Port with either values from Options or
	// ClientAdvertise.
	if err := s.setInfoHostPort(); err != nil {
		s.Fatalf("Error setting server INFO with ClientAdvertise value of %s, err=%v", opts.ClientAdvertise, err)
		l.Close()
		s.mu.Unlock()
		return
	}
	// Keep track of client connect URLs. We may need them later.
	s.clientConnectURLs = s.getClientConnectURLs()
	s.listener = l

	go s.acceptConnections(l, "Client", func(conn net.Conn) { s.createClient(conn) },
		func(_ error) bool {
			if s.isLameDuckMode() {
				// Signal that we are not accepting new clients
				s.ldmCh <- true
				// Now wait for the Shutdown...
				<-s.quitCh
				return true
			}
			return false
		})
	s.mu.Unlock()

	// Let the caller know that we are ready
	close(clr)
	clr = nil
}

func (s *Server) getServerListener(hp string) (net.Listener, error) {
	if s.listener != nil {
		return s.listener, s.listenerErr
	}

	return natsListen("tcp", hp)
}

var natsListenConfig = &net.ListenConfig{
	KeepAlive: -1,
}

// natsListen() is the same as net.Listen() except that TCP keepalives are
// disabled (to match Go's behavior before Go 1.13).
func natsListen(network, address string) (net.Listener, error) {
	return natsListenConfig.Listen(context.Background(), network, address)
}

func tierChild(t *testing.T, mode string, env []string, args ...string) (string, int) {
	t.Helper()
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(t.Context(), 3*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, executable, append([]string{"-test.run=^TestIntegrationChild$", "-test.v"}, args...)...)
	cmd.Env = append(os.Environ(), Env+"=", "TS_TIER_TEST_A=", "TS_TIER_TEST_B=",
		"TS_TIER_INTEGRATION_CHILD=1", "TS_TIER_CHILD_MODE="+mode, "GORACE=atexit_sleep_ms=0")
	cmd.Env = append(cmd.Env, env...)
	output, err := cmd.CombinedOutput()
	if ctx.Err() != nil || cmd.ProcessState == nil {
		t.Fatalf("tier child %s: %v, context=%v\n%s", mode, err, ctx.Err(), output)
	}
	return string(output), cmd.ProcessState.ExitCode()
}

func checkTierOutcome(t *testing.T, output string, code int, outcome, message string) {
	t.Helper()
	status, wantCode := "PASS", 0
	switch outcome {
	case "skip":
		status = "SKIP"
	case "fail":
		status, wantCode = "FAIL", 1
	}
	if code != wantCode || !strings.Contains(output, "--- "+status+": TestIntegrationChild") || !strings.Contains(output, message) {
		t.Fatalf("want %s (exit %d) containing %q; exit %d:\n%s", status, wantCode, message, code, output)
	}
	if outcome == "fail" && strings.Contains(output, "--- SKIP:") {
		t.Fatalf("required qualification skipped instead of failing:\n%s", output)
	}
}

func TestIntegrationChild(t *testing.T) {
	if os.Getenv("TS_TIER_INTEGRATION_CHILD") != "1" {
		t.Skip("child of the tier process scenarios")
	}
	switch os.Getenv("TS_TIER_CHILD_MODE") {
	case "qualification":
		values := Qualification(t, "TS_TIER_TEST_A", "TS_TIER_TEST_B")
		fmt.Printf("fixture-values=%q\n", values)
	case "no-variables":
		Qualification(t)
	case "unavailable":
		Unavailable(t, "needs %s", "a packet")
	case "integration":
		Integration(t)
		t.Log("integration test body ran")
	default:
		t.Fatal("unknown child scenario")
	}
}

// Env names the test tier of the current run.
const Env = "TS_TEST_TIER"

// QualificationTier is the Env value of a pre-deploy qualification run.
const QualificationTier = "qualification"

func Integration(t testing.TB) {
	t.Helper()
	if testing.Short() {
		t.Skip("integration tier: runs without -short on pushes to develop and main")
	}
}

func Qualification(t testing.TB, envs ...string) []string {
	t.Helper()
	if len(envs) == 0 {
		t.Fatal("tier.Qualification needs the environment variables that supply its fixture")
	}
	values := make([]string, len(envs))
	var missing []string
	for i, name := range envs {
		values[i] = os.Getenv(name)
		if values[i] == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		Unavailable(t, "qualification fixture not supplied: set %s", strings.Join(missing, ", "))
	}
	return values
}

func Unavailable(t testing.TB, format string, args ...any) {
	t.Helper()
	if Qualifying() {
		t.Fatalf(Env+"="+QualificationTier+": "+format, args...)
	}
	t.Skipf(format, args...)
}

